#include <FastLED.h>

// =========================
// LED-Konfiguration
// =========================

#define BASE_PIN    6
#define FLOWER_PIN  7

#define BASE_LEDS   26
#define FLOWER_LEDS 6

#define TOTAL_LEDS (BASE_LEDS + FLOWER_LEDS)

// WS2812B
#define LED_TYPE    WS2812B
#define COLOR_ORDER GRB

CRGB baseLeds[BASE_LEDS];
CRGB flowerLeds[FLOWER_LEDS];

// =========================
// Stromlimit
// =========================

// Konservatives Limit für Versorgung über den 5V-Pin.
// 500 mA = 2,5 W bei 5 V.
#define MAX_MILLIAMPS 500

// =========================
// Farben
// =========================

CRGB baseColor   = CRGB(255, 20, 80);   // Pink
CRGB flowerColor = CRGB(255, 255, 255); // Weiß

// =========================
// Animation
// =========================

struct BasePixel {
  bool active;
  uint8_t brightness;
  uint8_t targetBrightness;
  int8_t direction;
  uint32_t nextChange;
};

BasePixel pixels[BASE_LEDS];

// =========================
// Einschalt-Fade
// =========================

uint8_t startupBrightness = 0;
bool startupFinished = false;

uint32_t lastFrame = 0;

// =========================
// Hilfsfunktionen
// =========================

uint32_t estimateCurrent()
{
  uint32_t current = 0;

  // WS2812B ca. 60 mA bei voller Helligkeit.
  // Base
  for (int i = 0; i < BASE_LEDS; i++) {
    current += ((uint32_t)pixels[i].brightness * 60) / 255;
  }

  // Blumen
  for (int i = 0; i < FLOWER_LEDS; i++) {
    current += ((uint32_t)255 * 60) / 255;
  }

  return current;
}


// Skalierung für die gesamte Installation.
// Blumen bekommen Priorität.
void applyCurrentLimit()
{
  uint32_t flowerCurrent = FLOWER_LEDS * 60;

  if (flowerCurrent >= MAX_MILLIAMPS) {
    // Sollte bei 6 Blumen und 500 mA nicht passieren.
    for (int i = 0; i < FLOWER_LEDS; i++)
      flowerLeds[i].setRGB(0, 0, 0);

    return;
  }

  uint32_t remaining = MAX_MILLIAMPS - flowerCurrent;

  // Base-Strom bei aktueller Helligkeit berechnen
  uint32_t baseCurrent = 0;

  for (int i = 0; i < BASE_LEDS; i++) {
    baseCurrent += ((uint32_t)pixels[i].brightness * 60) / 255;
  }

  float scale = 1.0;

  if (baseCurrent > remaining && baseCurrent > 0) {
    scale = (float)remaining / (float)baseCurrent;
  }

  // Base darstellen
  for (int i = 0; i < BASE_LEDS; i++) {

    uint8_t b = pixels[i].brightness * scale;

    baseLeds[i] = baseColor;
    baseLeds[i].nscale8(b);
  }

  // Blumen bevorzugt hell
  for (int i = 0; i < FLOWER_LEDS; i++) {
    flowerLeds[i] = flowerColor;
  }
}


// Neue zufällige Base-LED auswählen
void activateRandomPixel()
{
  int index = random(0, BASE_LEDS);

  pixels[index].active = true;
  pixels[index].direction = 1;

  // Unterschiedliche Zielhelligkeiten
  pixels[index].targetBrightness = random(70, 220);

  pixels[index].nextChange = millis();
}


// =========================
// Setup
// =========================

void setup()
{
  delay(1000);

  randomSeed(esp_random());

  FastLED.addLeds<LED_TYPE, BASE_PIN, COLOR_ORDER>(
    baseLeds,
    BASE_LEDS
  );

  FastLED.addLeds<LED_TYPE, FLOWER_PIN, COLOR_ORDER>(
    flowerLeds,
    FLOWER_LEDS
  );

  FastLED.clear(true);

  // Base initialisieren
  for (int i = 0; i < BASE_LEDS; i++) {

    pixels[i].active = false;
    pixels[i].brightness = 0;
    pixels[i].targetBrightness = 0;
    pixels[i].direction = 1;
    pixels[i].nextChange = 0;
  }

  // Blumen zunächst aus
  for (int i = 0; i < FLOWER_LEDS; i++) {
    flowerLeds[i] = CRGB::Black;
  }

  FastLED.show();
}


// =========================
// Startup Fade
// =========================

void startupFade()
{
  if (startupFinished)
    return;

  static uint32_t lastFade = 0;

  if (millis() - lastFade < 30)
    return;

  lastFade = millis();

  startupBrightness++;

  // Blumen langsam hochfahren
  for (int i = 0; i < FLOWER_LEDS; i++) {
    flowerLeds[i] = flowerColor;
    flowerLeds[i].nscale8(startupBrightness);
  }

  // Base ebenfalls langsam einblenden
  for (int i = 0; i < BASE_LEDS; i++) {
    baseLeds[i] = baseColor;
    baseLeds[i].nscale8(startupBrightness / 2);
  }

  FastLED.show();

  if (startupBrightness >= 255) {
    startupFinished = true;

    // Einige Base-LEDs starten
    for (int i = 0; i < 4; i++) {
      activateRandomPixel();
    }
  }
}


// =========================
// Base Animation
// =========================

void updateBase()
{
  uint32_t now = millis();

  for (int i = 0; i < BASE_LEDS; i++) {

    if (!pixels[i].active)
      continue;

    // Fade-In
    if (pixels[i].direction > 0) {

      if (pixels[i].brightness < pixels[i].targetBrightness) {

        pixels[i].brightness += 3;

        if (pixels[i].brightness >= pixels[i].targetBrightness) {
          pixels[i].brightness = pixels[i].targetBrightness;

          // kurze Pause
          pixels[i].nextChange = now + random(300, 1200);
          pixels[i].direction = 0;
        }
      }
    }

    // Pause
    else if (pixels[i].direction == 0) {

      if (now >= pixels[i].nextChange) {
        pixels[i].direction = -1;
      }
    }

    // Fade-Out
    else {

      if (pixels[i].brightness > 0) {

        if (pixels[i].brightness > 3)
          pixels[i].brightness -= 3;
        else
          pixels[i].brightness = 0;

      } else {

        pixels[i].active = false;

        // zufällige Pause
        pixels[i].nextChange = now + random(100, 1000);
      }
    }
  }

  // Neue LEDs zufällig starten
  static uint32_t nextSpawn = 0;

  if (now >= nextSpawn) {

    activateRandomPixel();

    nextSpawn = now + random(150, 800);
  }
}


// =========================
// Loop
// =========================

void loop()
{
  if (!startupFinished) {

    startupFade();

    return;
  }

  updateBase();

  applyCurrentLimit();

  FastLED.show();

  delay(20);
}
